def policy(obs, P):
    cart_x = obs[0]
    cart_v = obs[1]
    pole_angle = obs[2]
    pole_ang_v = obs[3]
    if cart_v > P['t_hi']:
        return 0
    s = P['w_x']*cart_x + P['w_a']*pole_angle + P['w_av']*pole_ang_v + P['w_v']*cart_v + P['b']
    if s > 0:
        return 1
    else:
        return 0
